#include <stdio.h>


int main(void)
{
    int a[] = {1, 3, 2};
    int key = a[2];
    int j = 1;
    while (j >= 0 && a[j] > key) {
        a[j + 1] = a[j];
        j--;
    }
    a[j + 1] = key;
    printf("%d %d %d\n", a[0], a[1], a[2]);
    return 0;
}

#include <stdio.h>


int main(void)
{
    int a[] = {2, 3, 4, 1};
    int shifts = 0;
    for (int j = 2; j >= 0 && a[j] > 1; j--) {
        shifts++;
    }
    printf("%d\n", shifts);
    return 0;
}

#include <stdio.h>


int main(void)
{
    int shifts = 0;
    int key = 3;
    int previous = 3;
    if (previous > key) {
        shifts++;
    }
    printf("%d\n", shifts);
    return 0;
}
